LOGICPULSE.UI = LOGICPULSE.UI || {};

LOGICPULSE.UI.PortraitAnimator = class extends PIXI.Container {
    constructor(options) {
        super();
        options = options || {};
        this._folder = options.folder || LOGICPULSE.Assets.Folders.Portrait;
        this._actorId = options.actorId || 1;
        this._frameNames = LOGICPULSE.Assets.loadPortraitFrames(this._actorId);
        this._interval = options.interval || 2;   // matches the scene: 2 frames
        this._timer = 0;
        this._frameIndex = 0;
        this._direction = 1;

        this.x = options.x || 0;
        this.y = options.y || 0;

        this._createSprites();
    }

    _createSprites() {
        this._portraitSprites = [];
        for (var i = 0; i < this._frameNames.length; i++) {
            var sprite = LOGICPULSE.Assets.createSprite(this._folder, this._frameNames[i]);
            sprite.visible = false;
            this.addChild(sprite);
            this._portraitSprites.push(sprite);
        }
        if (this._portraitSprites.length > 0) {
            this._portraitSprites[0].visible = true;
            this._frameIndex = 0;
        }
    }

    update() {
        if (this._portraitSprites.length === 0) return;
        this._timer++;
        if (this._timer < this._interval) return;
        this._timer = 0;

        // Hide current
        this._portraitSprites[this._frameIndex].visible = false;

        // Move index (ping-pong)
        this._frameIndex += this._direction;
        if (this._frameIndex >= this._portraitSprites.length) {
            this._frameIndex = this._portraitSprites.length - 2;
            this._direction = -1;
        } else if (this._frameIndex < 0) {
            this._frameIndex = 1;
            this._direction = 1;
        }

        // Show new
        this._portraitSprites[this._frameIndex].visible = true;
    }
};


//=============================================================================
// LPHUDCity.js
//=============================================================================

LOGICPULSE.UI = LOGICPULSE.UI || {};

LOGICPULSE.UI.CityBackground = class extends PIXI.Container {
    constructor(options) {
        super();
        options = options || {};
        this._folder = options.folder || LOGICPULSE.Assets.Folders.CityPicture;
        this._components = LOGICPULSE.Assets.loadCityComponents();

        this.x = options.x || 0;
        this.y = options.y || 0;

        // Timers (mirroring the scene)
        this._cityFrameTimer = 0;
        this._citySkyTimer = 0;
        this._cityLightningTimer = 0;
        this._lightningHideTimer = undefined;
        this._blinkTimer = 0;

        // Config (hardcoded to match the scene)
        this._overlayIntervalMin = 150;
        this._overlayIntervalMax = 450;
        this._skyIntervalMin = 20;
        this._skyIntervalMax = 60;
        this._lightningIntervalMin = 1200;
        this._lightningIntervalMax = 2400;
        this._lightningDuration = 90;
        this._blinkPeriod = 120;
        this._blinkDuration = 60;

        this._createLayers();
        this._initRandom();
    }

    _createLayers() {
        var folder = this._folder;
        var comp = this._components;

        // Main
        var mainSprite = LOGICPULSE.Assets.createSprite(folder, comp.main);
        this.addChild(mainSprite);
        this._cityMain = mainSprite;

        // Overlays (B1-B14)
        this._overlaySprites = [];
        for (var i = 0; i < comp.overlays.length; i++) {
            var sprite = LOGICPULSE.Assets.createSprite(folder, comp.overlays[i]);
            sprite.visible = false;
            this.addChild(sprite);
            this._overlaySprites.push(sprite);
        }

        // Sky (S1, S2)
        this._skySprites = [];
        for (var j = 0; j < comp.sky.length; j++) {
            var sprite = LOGICPULSE.Assets.createSprite(folder, comp.sky[j]);
            sprite.visible = false;
            this.addChild(sprite);
            this._skySprites.push(sprite);
        }

        // Lightning sprites (array)
        this._lightningSprites = [];
        var lightningFiles = comp.lightning;
        for (var l = 0; l < lightningFiles.length; l++) {
            var sprite = LOGICPULSE.Assets.createSprite(folder, lightningFiles[l]);
            sprite.visible = false;
            this.addChild(sprite);
            this._lightningSprites.push(sprite);
        }

        // Blink sprite
        this._blinkSprite = LOGICPULSE.Assets.createSprite(folder, comp.blink);
        this._blinkSprite.visible = false;
        this.addChild(this._blinkSprite);

        // Frame
        var frameSprite = LOGICPULSE.Assets.createSprite(folder, comp.frame);
        this.addChild(frameSprite);
    }

    _initRandom() {
        if (this._overlaySprites.length > 0) {
            this._cityOverlayIndex = Math.floor(Math.random() * this._overlaySprites.length);
            this._overlaySprites[this._cityOverlayIndex].visible = true;
        }
        if (this._skySprites.length > 0) {
            this._citySkyIndex = Math.floor(Math.random() * this._skySprites.length);
            this._skySprites[this._citySkyIndex].visible = true;
        }
    }

    update() {
        // ---- Overlays – stay visible for 150~450 frames ----
        this._cityFrameTimer++;
        if (this._cityFrameTimer > this._overlayIntervalMin + Math.floor(Math.random() * (this._overlayIntervalMax - this._overlayIntervalMin))) {
            this._cityFrameTimer = 0;
            for (var i = 0; i < this._overlaySprites.length; i++) {
                this._overlaySprites[i].visible = false;
            }
            var count = 1 + Math.floor(Math.random() * 3);
            for (var j = 0; j < count; j++) {
                var idx = Math.floor(Math.random() * this._overlaySprites.length);
                this._overlaySprites[idx].visible = true;
            }
        }

        // ---- Sky – change every 20~60 frames ----
        this._citySkyTimer++;
        if (this._citySkyTimer > this._skyIntervalMin + Math.floor(Math.random() * (this._skyIntervalMax - this._skyIntervalMin))) {
            this._citySkyTimer = 0;
            for (var k = 0; k < this._skySprites.length; k++) {
                this._skySprites[k].visible = false;
            }
            var idx = Math.floor(Math.random() * this._skySprites.length);
            this._skySprites[idx].visible = true;
        }

        // ---- Lightning – trigger every ~1200-2400 frames ----
        this._cityLightningTimer++;
        if (this._cityLightningTimer > this._lightningIntervalMin + Math.floor(Math.random() * (this._lightningIntervalMax - this._lightningIntervalMin))) {
            this._cityLightningTimer = 0;
            for (var l = 0; l < this._lightningSprites.length; l++) {
                this._lightningSprites[l].visible = false;
            }
            var randomIndex = Math.floor(Math.random() * this._lightningSprites.length);
            this._lightningSprites[randomIndex].visible = true;
            this._lightningHideTimer = this._lightningDuration;
        }
        if (this._lightningHideTimer !== undefined && this._lightningHideTimer > 0) {
            this._lightningHideTimer--;
            if (this._lightningHideTimer <= 0) {
                for (var l = 0; l < this._lightningSprites.length; l++) {
                    this._lightningSprites[l].visible = false;
                }
                this._lightningHideTimer = undefined;
            }
        }

        // ---- Blink – flash every 10 frames, visible for 5 frames ----
        this._blinkTimer = (this._blinkTimer + 1) % this._blinkPeriod;
        this._blinkSprite.visible = (this._blinkTimer < this._blinkDuration);
    }
};


//=============================================================================
// UIHUDButton.js
//=============================================================================

LOGICPULSE.UI.HUDButton = class extends LOGICPULSE.UI.Element {
    constructor(options) {
        super();
        options = options || {};
        this._idleBitmap = options.idleBitmap;
        this._hoverBitmap = options.hoverBitmap;
        this._width = options.width || 100;
        this._height = options.height || 40;
        this._text = options.text || "";
        this._onClick = options.onClick || null;
        this._isHovered = false;
        this._textOffsetX = options.textOffsetX || 0;
        this._textOffsetY = options.textOffsetY || 0;
        this.move(options.x || 0, options.y || 0);
        this.create();
    }

    create() {
        // Idle sprite
        if (this._idleBitmap) {
            this._idleSprite = new Sprite(this._idleBitmap);
            this._idleSprite.width = this._width;
            this._idleSprite.height = this._height;
            this.addChild(this._idleSprite);
        }
        // Hover sprite
        if (this._hoverBitmap) {
            this._hoverSprite = new Sprite(this._hoverBitmap);
            this._hoverSprite.width = this._width;
            this._hoverSprite.height = this._height;
            this._hoverSprite.visible = false;
            this.addChild(this._hoverSprite);
        }
        // Text
        if (this._text) {
            this._textSprite = new Sprite(new Bitmap(this._width, this._height));
            this._textSprite.bitmap.fontFace = $gameSystem.mainFontFace();
            this._textSprite.bitmap.fontSize = this.options && this.options.fontSize ? this.options.fontSize : 20;
            this._textSprite.bitmap.textColor = "#ffffff";
            this._textSprite.bitmap.outlineColor = "rgba(0,0,0,0.8)";
            this._textSprite.bitmap.outlineWidth = 4;
            // Use full width/height, offset the origin
            this._textSprite.bitmap.drawText(
                this._text,
                this._textOffsetX,
                this._textOffsetY,
                this._width,
                this._height,
                "center"
            );
            this.addChild(this._textSprite);
        }
    }

    setHovered(hovered) {
        if (this._isHovered === hovered) return;
        this._isHovered = hovered;
        if (this._idleSprite) this._idleSprite.visible = !hovered;
        if (this._hoverSprite) this._hoverSprite.visible = hovered;
    }

    containsPoint(x, y) {
        var wx = this.x;
        var wy = this.y;
        var parent = this.parent;
        while (parent && parent !== SceneManager._scene) {
            wx += parent.x || 0;
            wy += parent.y || 0;
            parent = parent.parent;
        }
        return x >= wx && x <= wx + this._width &&
            y >= wy && y <= wy + this._height;
    }

    onClick() {
        if (this._onClick) this._onClick();
    }

    destroy(options) {
        if (this._idleSprite) { this._idleSprite.destroy(); this._idleSprite = null; }
        if (this._hoverSprite) { this._hoverSprite.destroy(); this._hoverSprite = null; }
        if (this._textSprite) { this._textSprite.destroy(); this._textSprite = null; }
        super.destroy(options);
    }
};


//=============================================================================
// LPHUDStatus.js
//=============================================================================

LOGICPULSE.UI = LOGICPULSE.UI || {};

LOGICPULSE.UI.StatusDisplay = class extends PIXI.Container {
    constructor(options) {
        super();
        options = options || {};
        this._provider = options.provider || LOGICPULSE.HUDProvider;
        this._layout = options.layout || LOGICPULSE.HUDLayout.CharacterStatusBox;

        // Position the container at the CharacterStatusBox location
        var boxPos = this._getBoxPosition("CharacterStatusBox");
        this.x = boxPos.x;
        this.y = boxPos.y;

        this._createGauges();
        this._createStatsTexts();
        this.updateAll();
    }

    _getBoxPosition(key) {
        var layoutImages = LOGICPULSE.HUDLayout.Images;
        for (var i = 0; i < layoutImages.length; i++) {
            if (layoutImages[i].key === key) {
                return { x: layoutImages[i].x, y: layoutImages[i].y };
            }
        }
        return { x: 0, y: 0 };
    }

    _createGauges() {
        this._gauges = {};
        var gaugeLayout = this._layout.Gauges;
        for (var key in gaugeLayout) {
            var cfg = gaugeLayout[key];
            var container = new PIXI.Container();
            container.x = cfg.x;
            container.y = cfg.y;

            // Prefix label (e.g., "HP")
            var labelWidth = 30;
            var labelText = new LOGICPULSE.UI.Text({
                x: -labelWidth - 4,
                y: 0,
                width: labelWidth,
                height: cfg.H,
                fontSize: cfg.fontSize || 16,
                textColor: cfg.color || "#ffffff",
                align: "right",
                fontFace: $gameSystem.mainFontFace()
            });
            labelText.setText(key);
            container.addChild(labelText);

            // Bar background
            var bg = new PIXI.Graphics();
            bg.beginFill(0x333333);
            bg.drawRect(0, 0, cfg.W, cfg.H);
            bg.endFill();
            container.addChild(bg);

            // Bar fill
            var fillColor = parseInt(cfg.color.replace('#', ''), 16) || 0xffffff;
            var fill = new PIXI.Graphics();
            fill.beginFill(fillColor);
            fill.drawRect(0, 0, cfg.W, cfg.H);
            fill.endFill();
            container.addChild(fill);

            this._gauges[key] = {
                container: container,
                fill: fill,
                maxWidth: cfg.W,
                height: cfg.H,
                color: fillColor
            };
            this.addChild(container);
        }
    }

    _createStatsTexts() {
        this._statsTexts = {};
        var layout = this._layout;
        var keys = ["Attack", "Defence", "agility", "MagicAttack", "MagicDefence", "Weapon", "Shield", "Head", "Body", "Accessory"];
        for (var i = 0; i < keys.length; i++) {
            var key = keys[i];
            var cfg = layout[key];
            if (!cfg) continue;
            var text = new LOGICPULSE.UI.Text({
                x: cfg.x,
                y: cfg.y,
                width: cfg.w,
                height: cfg.h,
                fontSize: cfg.fontSize,
                textColor: cfg.color,
                align: cfg.align || "left",
                fontFace: cfg.font || $gameSystem.mainFontFace()
            });
            this.addChild(text);
            this._statsTexts[key] = text;
        }
    }

    updateAll() {
        this.updateGauges();
        this.updateStatsTexts();
    }

    updateGauges() {
        var provider = this._provider;
        var gauges = {
            HP: { value: provider.getHp(), max: provider.getMaxHp() },
            MP: { value: provider.getMp(), max: provider.getMaxMp() },
            TP: { value: provider.getTp(), max: provider.getMaxTp() }
        };
        for (var key in gauges) {
            var g = this._gauges[key];
            if (!g) continue;
            var val = gauges[key].value;
            var max = gauges[key].max || 1;
            var ratio = Math.min(1, Math.max(0, val / max));
            var newWidth = Math.floor(ratio * g.maxWidth);
            g.fill.clear();
            g.fill.beginFill(g.color);
            g.fill.drawRect(0, 0, newWidth, g.height);
            g.fill.endFill();
        }
    }

    updateStatsTexts() {
        var provider = this._provider;
        this._statsTexts.Attack.setText("ATK: " + provider.getAttack());
        this._statsTexts.Defence.setText("DEF: " + provider.getDefence());
        this._statsTexts.agility.setText("AGI: " + provider.getAgility());
        this._statsTexts.MagicAttack.setText("MAT: " + provider.getMagicAttack());
        this._statsTexts.MagicDefence.setText("MDF: " + provider.getMagicDefence());
        this._statsTexts.Weapon.setText("WPN: " + provider.getWeapon());
        this._statsTexts.Shield.setText("SH: " + provider.getShield());
        this._statsTexts.Head.setText("HD: " + provider.getHead());
        this._statsTexts.Body.setText("BD: " + provider.getBody());
        this._statsTexts.Accessory.setText("ACC: " + provider.getAccessory());
    }
};


//=============================================================================
// LPHUDQuest.js
//=============================================================================

//=============================================================================
// LPHUDQuest.js – with auto‑select active objective
//=============================================================================

LOGICPULSE.UI = LOGICPULSE.UI || {};

LOGICPULSE.UI.HUDQuestDisplay = class extends PIXI.Container {
    constructor(options) {
        super();
        options = options || {};
        this._provider = options.provider || LOGICPULSE.HUDProvider;
        this._layout = options.layout || LOGICPULSE.HUDLayout.QuestBox;

        var boxPos = this._getBoxPosition("QuestBox");
        this.x = boxPos.x;
        this.y = boxPos.y;

        this._objScrollY = 0;
        this._objContentHeight = 0;
        this._descScrollY = 0;
        this._descContentHeight = 0;
        this._lastDescText = '';


        this._selectedObjectiveId = null;
        this._selectedObjectiveState = 0;
        this._objectiveRects = [];
        this._currentDetails = null;

        this._createStaticTexts();
        this._createNotesLabel();
        this._createObjectivesMaskAndContainer();
        this._createDescriptionMaskAndContainer();
        this._createHintText();
        this.updateAll();
    }

    _getBoxPosition(key) {
        var layoutImages = LOGICPULSE.HUDLayout.Images;
        for (var i = 0; i < layoutImages.length; i++) {
            if (layoutImages[i].key === key) {
                return { x: layoutImages[i].x, y: layoutImages[i].y };
            }
        }
        return { x: 0, y: 0 };
    }

    _createStaticTexts() {
        this._texts = {};
        var layout = this._layout;
        var keys = ["CaseTitle", "CaseNumber"];
        for (var i = 0; i < keys.length; i++) {
            var key = keys[i];
            var cfg = layout[key];
            if (!cfg) continue;
            var text = new LOGICPULSE.UI.Text({
                x: cfg.x,
                y: cfg.y,
                width: cfg.w,
                height: cfg.h,
                fontSize: cfg.fontSize,
                textColor: cfg.color,
                align: cfg.align || "left",
                fontFace: cfg.font || $gameSystem.mainFontFace()
            });
            this.addChild(text);
            this._texts[key] = text;
        }
    }
    _createNotesLabel() {
        const cfg = this._layout.Notes;
        if (!cfg) return;

        this._notesLabel = new LOGICPULSE.UI.Text({
            x: cfg.x,
            y: cfg.y,
            width: cfg.w,
            height: cfg.h,
            fontSize: cfg.fontSize || 32,
            textColor: cfg.color || "#ff8000",
            align: cfg.align || "left",
            fontFace: cfg.font || $gameSystem.mainFontFace(),
            text: "Current Case Note:"
        });

        this.addChild(this._notesLabel);
    }



    _createHintText() {
        const maskCfg = this._layout.HintMask;
        const textCfg = this._layout.HintText;

        if (!maskCfg) return;

        // --- MASK ---
        this._hintMask = new PIXI.Graphics();
        this._hintMask.beginFill(0xffffff);
        this._hintMask.drawRect(maskCfg.x, maskCfg.y, maskCfg.w, maskCfg.h);
        this._hintMask.endFill();
        this.addChild(this._hintMask);

        // --- CONTAINER ---
        this._hintContainer = new PIXI.Container();
        this._hintContainer.x = maskCfg.x;
        this._hintContainer.y = maskCfg.y;
        this._hintContainer.mask = this._hintMask;
        this.addChild(this._hintContainer);

        // --- TEXT STYLE ---
        this._hintStyle = new PIXI.TextStyle({
            fontFamily: $gameSystem.mainFontFace(),
            fontSize: textCfg.fontSize || maskCfg.fontSize || 16,
            fill: maskCfg.color || "#ff8000",
            align: textCfg.align || "left",
            wordWrap: true,
            wordWrapWidth: maskCfg.w
        });

        // --- TEXT INSIDE CONTAINER ---
        this._hintText = new PIXI.Text("", this._hintStyle);

        // IMPORTANT: relative to container, NOT screen
        this._hintText.x = textCfg.x || 0;
        this._hintText.y = textCfg.y || 0;   // ← moves text down inside the box

        this._hintContainer.addChild(this._hintText);
    }




    _createObjectivesMaskAndContainer() {
        var L = this._layout;
        var maskCfg = L.ObjectivesMask;
        var boxCfg = L.ObjectivesBox;

        this._objMask = new PIXI.Graphics();
        this._objMask.beginFill(0xffffff);
        this._objMask.drawRect(maskCfg.x, maskCfg.y, maskCfg.w, maskCfg.h);
        this._objMask.endFill();
        this._objMask.visible = true;
        this.addChild(this._objMask);

        this._objContainer = new PIXI.Container();
        this._objContainer.x = maskCfg.x;
        this._objContainer.y = maskCfg.y;
        this._objContainer.mask = this._objMask;
        this.addChild(this._objContainer);

        this._objMaskRect = { x: maskCfg.x, y: maskCfg.y, w: maskCfg.w, h: maskCfg.h };
        this._objBoxHeight = boxCfg.h || 36;
        var spacing = boxCfg.spacing || 5;
        if (spacing < 1) spacing = 5;
        this._objSpacing = spacing;
    }

    _createDescriptionMaskAndContainer() {
        var L = this._layout;
        var descMaskCfg = L.DescriptionMask;
        var descCfg = L.Description;

        this._descMask = new PIXI.Graphics();
        this._descMask.beginFill(0xffffff);
        this._descMask.drawRect(descMaskCfg.x, descMaskCfg.y, descMaskCfg.w, descMaskCfg.h);
        this._descMask.endFill();
        this._descMask.visible = true;
        this.addChild(this._descMask);

        this._descContainer = new PIXI.Container();
        this._descContainer.x = descMaskCfg.x;
        this._descContainer.y = descMaskCfg.y;
        this._descContainer.mask = this._descMask;
        this.addChild(this._descContainer);

        this._descText = new LOGICPULSE.UI.Text({
            x: descCfg.x || 0,
            y: descCfg.y || 0,
            width: descCfg.w || descMaskCfg.w,
            height: 999,
            fontSize: descCfg.fontSize || 20,
            textColor: descCfg.color || "#ffffff",
            align: descCfg.align || "left",
            fontFace: descCfg.font || $gameSystem.mainFontFace()
        });
        this._descContainer.addChild(this._descText);

        this._descMaskRect = { x: descMaskCfg.x, y: descMaskCfg.y, w: descMaskCfg.w, h: descMaskCfg.h };
    }

    updateAll() {
        var provider = this._provider;
        var details = provider.getPriorityQuestDetails();
        this._currentDetails = details;

        this._texts.CaseTitle.setText(provider.getCaseTitle());
        this._texts.CaseNumber.setText(provider.getCaseNumber());

        var showInactive = details ? details.showInactive : false;
        this._updateObjectives(details, showInactive);
        this._updateDescription(details);
        this._autoSelectDefaultObjective(); // ← auto‑select active objective
        this._updateHint();
    }

    _updateObjectives(details, showInactive) {
        this._objContainer.removeChildren();
        this._objectiveRects = [];

        if (!details || !details.objectives || details.objectives.length === 0) {
            this._objContentHeight = 0;
            this._objScrollY = 0;
            this._objContainer.y = this._objMaskRect.y;
            return;
        }

        var filteredObjectives = details.objectives;
        if (!showInactive) {
            filteredObjectives = details.objectives.filter(function(obj) {
                return obj.state !== 0;
            });
        }

        if (filteredObjectives.length === 0) {
            this._objContentHeight = 0;
            this._objScrollY = 0;
            this._objContainer.y = this._objMaskRect.y;
            return;
        }

        var y = 0;
        var S = LOGICPULSE.Constants.Quest.ObjectiveState;
        var boxH = this._objBoxHeight;
        var spacing = this._objSpacing;
        var maskW = this._objMaskRect.w;

        for (var obj of filteredObjectives) {
            var stateText = "Inactive";
            var color = "#ffffff";
            if (obj.state === S.Active) {
                stateText = "Active";
                color = "#ffffff";
            } else if (obj.state === S.Completed) {
                stateText = "Completed";
                color = "#44ff44";
            } else if (obj.state === S.Failed) {
                stateText = "Failed";
                color = "#ff4444";
            }

            // Background
            var boxSprite = LOGICPULSE.Assets.createSprite(
                LOGICPULSE.Assets.Folders.HUD,
                LOGICPULSE.Assets.Images.HUD.QuestObjectiveBox
            );
            if (boxSprite && boxSprite.texture) {
                boxSprite.width = maskW;
                boxSprite.height = boxH;
                boxSprite.x = 0;
                boxSprite.y = y;
                this._objContainer.addChild(boxSprite);
            } else {
                var bg = new PIXI.Graphics();
                bg.beginFill(0x333333);
                bg.drawRect(0, y, maskW, boxH);
                bg.endFill();
                this._objContainer.addChild(bg);
            }

            var textCfg = this._layout.ObjectivesTexts || { x: 40, y: 0, w: 595, h: 36, align: "center", fontSize: 20, color: "#ffffff" };
            var text = new LOGICPULSE.UI.Text({
                x: textCfg.x,
                y: y + textCfg.y,
                width: textCfg.w || maskW - textCfg.x - 10,
                height: textCfg.h || boxH,
                fontSize: textCfg.fontSize || 20,
                textColor: color,
                align: textCfg.align || "left",
                text: obj.description + " [" + stateText + "]",
                fontFace: textCfg.font || $gameSystem.mainFontFace()
            });
            this._objContainer.addChild(text);

            this._objectiveRects.push({
                id: obj.id,
                state: obj.state,
                y: y,
                height: boxH,
                hint: obj.hint || ""
            });

            y += boxH + spacing;
        }

        this._objContentHeight = Math.max(0, y - spacing);
        var maxScroll = Math.max(0, this._objContentHeight - this._objMaskRect.h);
        if (this._objScrollY < -maxScroll) this._objScrollY = -maxScroll;
        if (this._objScrollY > 0) this._objScrollY = 0;
        this._objContainer.y = this._objMaskRect.y + this._objScrollY;
    }

    _updateDescription(details) {
        var text = "";
        if (details && details.objectives) {
            var priority = this._provider.getPriorityQuest();
            if (priority) {
                for (var obj of details.objectives) {
                    if (obj.state === LOGICPULSE.Constants.Quest.ObjectiveState.Active) {
                        var note = LOGICPULSE.QuestManager.getOnScreenExtraNote(
                            priority.chapterId,
                            priority.questId,
                            obj.id
                        );
                        if (note) {
                            text = note;
                            break;
                        }
                    }
                }
            }
        }
        if (!text && details) {
            text = details.description || "";
        }

        if (text !== this._lastDescText) {
            this._lastDescText = text;
            this._descScrollY = 0;
        }

        this._descText.setText(text);

        var width = this._descText._width || this._descMaskRect.w;
        var fontSize = this._descText._fontSize || 20;
        var fontFace = this._descText._fontFace || $gameSystem.mainFontFace();

        var style = new PIXI.TextStyle({
            fontFamily: fontFace,
            fontSize: fontSize,
            fill: "#ffffff",
            align: this._descText._align || "left",
            wordWrap: true,
            wordWrapWidth: width,
            breakWords: true
        });
        var measureText = new PIXI.Text(text || " ", style);
        var textHeight = measureText.height;
        measureText.destroy();

        var padding = 20;
        var bottomPadding = 30;
        this._descContentHeight = Math.max(textHeight + padding + bottomPadding, this._descMaskRect.h);

        var maxScroll = Math.max(0, this._descContentHeight - this._descMaskRect.h);
        if (this._descScrollY < -maxScroll) this._descScrollY = -maxScroll;
        if (this._descScrollY > 0) this._descScrollY = 0;
        this._descContainer.y = this._descMaskRect.y + this._descScrollY;
    }

    // ---- Auto‑select the last active objective ----
    _autoSelectDefaultObjective() {
        if (!this._currentDetails || !this._currentDetails.objectives) return;

        // If we already have a selected objective that exists, keep it.
        var exists = this._objectiveRects.some(function(r) { return r.id === this._selectedObjectiveId; }.bind(this));
        if (exists) return;

        // Find active objectives (state === 1)
        var activeObjectives = this._currentDetails.objectives.filter(function(obj) {
            return obj.state === LOGICPULSE.Constants.Quest.ObjectiveState.Active;
        });

        var targetObj = null;
        if (activeObjectives.length > 0) {
            // Pick the last active objective (by index)
            targetObj = activeObjectives[activeObjectives.length - 1];
        } else {
            // If no active objective, pick the first visible objective (or first overall)
            // We'll pick the first objective that is not inactive, or first overall.
            var visibleObjectives = this._currentDetails.objectives.filter(function(obj) {
                return obj.state !== 0;
            });
            targetObj = visibleObjectives.length > 0 ? visibleObjectives[0] : this._currentDetails.objectives[0];
        }

        if (targetObj) {
            this._selectedObjectiveId = targetObj.id;
            this._selectedObjectiveState = targetObj.state;
        } else {
            this._selectedObjectiveId = null;
        }
    }

    // ---- Update OnScreenHint text and color ----
    _updateHint() {
        if (!this._hintText) return;
        var hint = "";
        var color = "#ff8000";
        var selected = this._objectiveRects.find(function(r) {
            return r.id === this._selectedObjectiveId;
        }.bind(this));

        if (selected) {
            hint = selected.hint || "";
            if (selected.state === LOGICPULSE.Constants.Quest.ObjectiveState.Active) {
                color = "#ffffff";
            } else if (selected.state === LOGICPULSE.Constants.Quest.ObjectiveState.Completed) {
                color = "#44ff44";
            } else if (selected.state === LOGICPULSE.Constants.Quest.ObjectiveState.Failed) {
                color = "#ff4444";
            } else {
                color = "#888888";
            }
        }

        this._hintText.text = hint || "";
        this._hintStyle.fill = color;
        this._hintText.style = this._hintStyle;
    }

    // ---- Click handling ----
    handleClick(mx, my) {
        var containerWorldX = this.x + this._objContainer.x;
        var containerWorldY = this.y + this._objContainer.y;
        var rects = this._objectiveRects;
        for (var i = 0; i < rects.length; i++) {
            var r = rects[i];
            var rectWorldY = containerWorldY + r.y;
            if (mx >= containerWorldX && mx <= containerWorldX + this._objMaskRect.w &&
                my >= rectWorldY && my <= rectWorldY + r.height) {
                this._selectedObjectiveId = r.id;
                this._selectedObjectiveState = r.state;
                this._updateHint();
                return true;
            }
        }
        return false;
    }

    // ---- Mouse wheel ----
    handleWheel(mx, my, delta) {
        var rect = this._objMaskRect;
        var worldX = this.x + rect.x;
        var worldY = this.y + rect.y;
        if (mx >= worldX && mx <= worldX + rect.w &&
            my >= worldY && my <= worldY + rect.h) {
            var maxScroll = Math.max(0, this._objContentHeight - rect.h);
            if (maxScroll > 0) {
                this._objScrollY -= delta * 10;
                this._objScrollY = Math.max(-maxScroll, Math.min(0, this._objScrollY));
                this._objContainer.y = rect.y + this._objScrollY;
                return true;
            }
            return false;
        }

        var descRect = this._descMaskRect;
        var worldX2 = this.x + descRect.x;
        var worldY2 = this.y + descRect.y;
        if (mx >= worldX2 && mx <= worldX2 + descRect.w &&
            my >= worldY2 && my <= worldY2 + descRect.h) {
            var maxScrollDesc = Math.max(0, this._descContentHeight - descRect.h);
            if (maxScrollDesc > 0) {
                this._descScrollY -= delta * 10;
                this._descScrollY = Math.max(-maxScrollDesc, Math.min(0, this._descScrollY));
                this._descContainer.y = descRect.y + this._descScrollY;
                return true;
            }
        }
        return false;
    }
};


//=============================================================================
// LPHUDScene.js
//=============================================================================

LOGICPULSE.Scene_HUD = class extends Scene_Base {
    constructor() {
        super();
        // No timers here – they're inside the dedicated objects
    }

    create() {
        super.create();
        this._controller = new LOGICPULSE.HUDController(this);

        // 1. Background (full screen)
        this.createBackgroundImage();

        // 2. City (animated background)
        this.createCity();

        // 3. Boxes (all except MapBox)
        this.createBoxes();

        // 4. Portrait (on top of portrait box)
        this.createPortrait();

        // 5. MapBox (on top of portrait, behind buttons)
        this.createMapBox();

        // 6. Header texts (top header)
        this.createHeaderContent();

        // 7. Status content (gauges + stats)
        this.createStatusContent();

        // 8. Quest content
        this.createQuestContent();

        // 9. Buttons (on top)
        this.createButtons();

        this._fadeIn = true;
    }

    // ---- Background ----
    createBackgroundImage() {
        var bgName = LOGICPULSE.Assets.Images.HUD.Background;
        var sprite = LOGICPULSE.Assets.createSprite(LOGICPULSE.Assets.Folders.HUD, bgName);
        sprite.x = 0;
        sprite.y = 0;
        this.addChild(sprite);
        this._backgroundSprite = sprite;
    }

    // ---- Boxes ----
    createBoxes() {
        var layoutImages = LOGICPULSE.HUDLayout.Images;
        for (var i = 0; i < layoutImages.length; i++) {
            var img = layoutImages[i];
            if (img.key === "Background") continue;
            if (img.key === "MapBox") continue;   // we'll add it later
            var sprite = LOGICPULSE.Assets.createSprite(LOGICPULSE.Assets.Folders.HUD, img.name);
            sprite.x = img.x;
            sprite.y = img.y;
            this.addChild(sprite);
            if (img.key === "TopHeader") this._headerSprite = sprite;
            else if (img.key === "CaseNotesBox") this._caseNotesBoxSprite = sprite;
            else if (img.key === "CharacterStatusBox") this._statusBoxSprite = sprite;
            else if (img.key === "QuestBox") this._questBoxSprite = sprite;
            else if (img.key === "PortraitBox") this._portraitBoxSprite = sprite;
            // MapBox is handled separately
        }
    }

    // ---- City ----
    createCity() {
        var layout = LOGICPULSE.HUDLayout.animations.CityPicture;
        this._city = new LOGICPULSE.UI.CityBackground({
            x: layout.x,
            y: layout.y,
            overlayIntervalMin: 150,
            overlayIntervalMax: 450,
            skyIntervalMin: 20,
            skyIntervalMax: 60,
            lightningIntervalMin: 1200,
            lightningIntervalMax: 2400,
            lightningDuration: 90,
            blinkPeriod: 10,
            blinkDuration: 5
        });
        this.addChild(this._city);
    }

    // ---- Portrait ----
    createPortrait() {
        var layout = LOGICPULSE.HUDLayout.animations.Portrait;
        var actor = LOGICPULSE.HUDProvider.getActor();
        var actorId = actor ? actor.actorId() : 1;
        this._portrait = new LOGICPULSE.UI.PortraitAnimator({
            x: layout.x,
            y: layout.y,
            actorId: actorId,
            interval: 4
        });
        this.addChild(this._portrait);
    }

    createMapBox() {
        // Find the MapBox entry from the layout
        var layoutImages = LOGICPULSE.HUDLayout.Images;
        var mapBoxData = null;
        for (var i = 0; i < layoutImages.length; i++) {
            if (layoutImages[i].key === "MapBox") {
                mapBoxData = layoutImages[i];
                break;
            }
        }
        if (!mapBoxData) return;

        var sprite = LOGICPULSE.Assets.createSprite(
            LOGICPULSE.Assets.Folders.HUD,
            mapBoxData.name
        );
        sprite.x = mapBoxData.x;
        sprite.y = mapBoxData.y;
        this.addChild(sprite);
        this._mapBoxSprite = sprite;
    }

    // ---- Header Texts ----
    createHeaderContent() {
        this._headerTexts = {};
        var layout = LOGICPULSE.HUDLayout.TopHeaderText;
        for (var key in layout) {
            var cfg = layout[key];
            var textOptions = {
                x: cfg.x,
                y: cfg.y,
                width: cfg.w,
                height: cfg.h,
                fontSize: cfg.fontSize,
                textColor: cfg.color,
                align: cfg.align || "left"
            };

            // --- Apply glow outline to "Level" text ---
            if (key === "Level") {
                // Use the same color as the text but with transparency and wider outline
                textOptions.outlineColor = "rgba(46,89,169,0.6)";
                textOptions.outlineWidth = 4;
            } else if (key === "LevelValue") {
                textOptions.outlineColor = "rgba(46,89,169,0.6)"; // match its text color
                textOptions.outlineWidth = 4;
            } else {
                // Default outline (black, 4px) for other texts
                textOptions.outlineColor = "rgba(0,0,0,0.8)";
                textOptions.outlineWidth = 4;
            }

            var text = new LOGICPULSE.UI.Text(textOptions);
            this.addChild(text);
            this._headerTexts[key] = text;
        }
        this.updateHeaderTexts();
    }

    updateHeaderTexts() {
        var provider = LOGICPULSE.HUDProvider;
        this._headerTexts.Level.setText("Lv.");
        this._headerTexts.LevelValue.setText(provider.getLevel());
        this._headerTexts.Gold.setText("Credit");
        this._headerTexts.GoldValue.setText(provider.getGold());
    }

    // ---- Status Content ----
    createStatusContent() {
        this._statusDisplay = new LOGICPULSE.UI.StatusDisplay();
        this.addChild(this._statusDisplay);
    }

    // ---- Quest Content ----
    createQuestContent() {
        this._questDisplay = new LOGICPULSE.UI.HUDQuestDisplay();
        this.addChild(this._questDisplay);
    }

    // ---- Buttons ----
    createButtons() {
        this._buttons = [];
        var leftLayout = LOGICPULSE.HUDLayout.LeftButtons;
        var rightLayout = LOGICPULSE.HUDLayout.RightButtons;
        var folders = LOGICPULSE.Assets.Folders;
        var images = LOGICPULSE.Assets.Images.HUD;

        // ---- Left buttons ----
        var leftKeys = ["Inventory", "Equipment", "QuestDB", "Skill", "SaveLoad", "Setting", "Exit"];
        var leftActions = {
            Inventory: function () { SceneManager.push(LOGICPULSE.Scenes.Inventory); },
            Equipment: function () { SceneManager.push(Scene_Equip); },
            QuestDB: function () { SceneManager.push(LOGICPULSE.Scene_QuestLog); },
            Skill: function () { SceneManager.push(Scene_Skill); },
            SaveLoad: function () { SceneManager.push(LOGICPULSE.Scenes.SaveLoad); },
            Setting: function () { SceneManager.push(Scene_Options); },
            Exit: function () { SceneManager.exit(); }
        };
        // Default texts – you can override by adding a "text" field in the layout for each button
        var defaultLeftTexts = ["Inventory", "Equipment", "Quest Database", "Skill Database", "Save/Load", "Setting", "Exit Game"];

        for (var i = 0; i < leftKeys.length; i++) {
            var key = leftKeys[i];
            var cfg = leftLayout[key];
            if (!cfg) continue;

            // Use cfg.text if available, otherwise use default from array
            var buttonText = cfg.text || defaultLeftTexts[i];

            var idleBitmap, hoverBitmap;
            if (key === "Exit") {
                idleBitmap = LOGICPULSE.Assets.load(folders.HUD, images.ButtonExitIdle);
                hoverBitmap = LOGICPULSE.Assets.load(folders.HUD, images.ButtonExitHover);
            } else {
                idleBitmap = LOGICPULSE.Assets.load(folders.HUD, images.LeftButtonIdle);
                hoverBitmap = LOGICPULSE.Assets.load(folders.HUD, images.LeftButtonHover);
            }

            var btn = new LOGICPULSE.UI.HUDButton({
                x: cfg.x,
                y: cfg.y,
                width: cfg.width,
                height: cfg.height,
                idleBitmap: idleBitmap,
                hoverBitmap: hoverBitmap,
                text: buttonText,
                fontSize: 28,
                textColor: "#ffffff",
                textOffsetX: cfg.textOffsetX || 0,
                textOffsetY: cfg.textOffsetY || 0,
                onClick: leftActions[key]
            });
            this.addChild(btn);
            this._buttons.push(btn);
            this._controller.registerButton(btn);
        }

        // ---- Right buttons (Map) ----
        var rightKeys = ["Map"];
        var rightActions = {
            Map: function () { /* placeholder */ }
        };
        var rightIdle = [images.ButtonMapIdle];
        var rightHover = [images.ButtonMapHover];

        for (var j = 0; j < rightKeys.length; j++) {
            var key = rightKeys[j];
            var cfg = rightLayout[key];
            if (!cfg) continue;

            var buttonText = cfg.text || "Inspect Map";

            var btn = new LOGICPULSE.UI.HUDButton({
                x: cfg.x,
                y: cfg.y,
                width: cfg.width,
                height: cfg.height,
                idleBitmap: LOGICPULSE.Assets.load(folders.HUD, rightIdle[j]),
                hoverBitmap: LOGICPULSE.Assets.load(folders.HUD, rightHover[j]),
                text: buttonText,
                fontSize: 28,
                textColor: "#ffffff",
                textOffsetX: cfg.textOffsetX || 0,
                textOffsetY: cfg.textOffsetY || 0,
                onClick: rightActions[key]
            });
            this.addChild(btn);
            this._buttons.push(btn);
            this._controller.registerButton(btn);
        }
    }

    // ---- Update loop ----
    update() {
        LOGICPULSE.Mouse.update();
        super.update();

        // Update animations
        if (this._city) this._city.update();
        if (this._portrait) this._portrait.update();

        // Update HUD data
        this.updateHeaderTexts();
        if (this._statusDisplay) this._statusDisplay.updateAll();
        if (this._questDisplay) this._questDisplay.updateAll();

        // ---- Wheel handling for quest display ----
        var wheelDelta = LOGICPULSE.Mouse._wheelDelta;
        if (wheelDelta !== 0 && this._questDisplay) {
            var mx = LOGICPULSE.Mouse.x();
            var my = LOGICPULSE.Mouse.y();
            var consumed = this._questDisplay.handleWheel(mx, my, wheelDelta);
            if (consumed) {
                LOGICPULSE.Mouse._wheelDelta = 0; // reset to prevent further use
            }
        }
        // ---- Click handling for objectives ----
        if (TouchInput.isTriggered() && this._questDisplay) {
            var mx = TouchInput.x;
            var my = TouchInput.y;
            this._questDisplay.handleClick(mx, my);
        }

        // Buttons
        this._controller.update();

        // Cancel
        if (Input.isTriggered('cancel')) {
            SceneManager.pop();
        }
    }
};


//=============================================================================
// Main.js
//=============================================================================

LOGICPULSE.Scenes.HUD = LOGICPULSE.Scene_HUD;

// Plugin command
var _LOGICPULSE_MAIN_HUD_UI_pluginCommand = Game_Interpreter.prototype.pluginCommand;
Game_Interpreter.prototype.pluginCommand = function(command, args) {
    _LOGICPULSE_MAIN_HUD_UI_pluginCommand.call(this, command, args);
    if (command === 'OpenHUD') {
        SceneManager.push(LOGICPULSE.Scene_HUD);
    }
};

